const Fastify = require('fastify');
const { PreferenceStore } = require('./preferences');
const { authenticateUser } = require('./auth');

const fastify = Fastify();

fastify.register(async function preferencesRoutes(instance) {
  instance.addHook('preHandler', async (request, reply) => {
    const user = await authenticateUser(request);
    if (!user) {
      return reply.status(401).send({ error: 'Unauthorized' });
    }
    request.user = user;
  });

  instance.get('/api/users/:userId/preferences/digest', async (request, reply) => {
    const { userId } = request.params;

    // Verify requesting user matches target userId
    if (request.user.id !== userId && !request.user.isAdmin) {
      return reply.status(403).send({ error: 'Forbidden: cannot view preferences of another user' });
    }

    const prefs = await PreferenceStore.findByUserId(userId);
    if (!prefs) {
      return reply.status(404).send({ error: 'Preferences not found' });
    }

    return reply.send({
      userId,
      frequency: prefs.digestFrequency,
      unsubscribedAll: prefs.unsubscribed
    });
  });
});

fastify.listen({ port: 8095 });
